const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define point geometries for eastern and western locations
    const easternPoint = ee.Geometry.Point([-137.527803, 48.504441]);
    const westernPoint = ee.Geometry.Point([-169.318365, 46.750838]);

    // 2. Define date ranges
    const baselineStart = '2003-01-01';
    const baselineEnd = '2012-12-31';
    const targetStart = '2016-01-01';
    const targetEnd = '2016-01-31';

    // 3. Function to get SST collection for a given date range
    function getSSTCollection(startDate, endDate) {
        return ee.ImageCollection('NOAA/CDR/OISST/V2_1')
            .filterDate(startDate, endDate)
            .select('sst'); // Sea surface temperature in °C
    }

    // 4. Function to calculate anomaly for a point
    function calculateAnomaly(point, baselineCol, targetCol) {
        // Calculate baseline mean (2003-2012 January average)
        const baselineMean = baselineCol
            .filter(ee.Filter.calendarRange(1, 1, 'month'))
            .mean();

        // Calculate 2016 January mean
        const targetMean = targetCol.mean();

        // Calculate anomaly (2016 mean - baseline mean)
        return targetMean.subtract(baselineMean);
    }

    // 5. Get collections
    const baselineCol = getSSTCollection(baselineStart, baselineEnd);
    const targetCol = getSSTCollection(targetStart, targetEnd);

    // Check data availability
    const baselineSize = baselineCol.size().getInfo();
    const targetSize = targetCol.size().getInfo();

    console.log(`Baseline (2003-2012) images: ${baselineSize}`);
    console.log(`Target (2016-01) images: ${targetSize}`);

    if (baselineSize === 0 || targetSize === 0) {
        console.log("<answer>C1</answer>");
        return;
    }

    // 6. Calculate anomalies for both points
    const easternAnomalyImg = calculateAnomaly(easternPoint, baselineCol, targetCol);
    const westernAnomalyImg = calculateAnomaly(westernPoint, baselineCol, targetCol);

    // 7. Extract values using reduceRegion with appropriate scale
    const easternAnomaly = ee.Number(easternAnomalyImg
        .reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: easternPoint,
            scale: 25000, // OISST native resolution ~25km
            maxPixels: 1e9
        }).get('sst'));

    const westernAnomaly = ee.Number(westernAnomalyImg
        .reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: westernPoint,
            scale: 25000,
            maxPixels: 1e9
        }).get('sst'));

    // 8. Get pixel counts to check for valid data
    const easternCount = ee.Number(easternAnomalyImg
        .reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: easternPoint,
            scale: 25000,
            maxPixels: 1e9
        }).get('sst'));

    const westernCount = ee.Number(westernAnomalyImg
        .reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: westernPoint,
            scale: 25000,
            maxPixels: 1e9
        }).get('sst'));

    // 9. Get values and validate
    const easternVal = easternAnomaly.getInfo();
    const westernVal = westernAnomaly.getInfo();
    const easternCnt = easternCount.getInfo();
    const westernCnt = westernCount.getInfo();

    console.log(`Eastern anomaly: ${easternVal?.toFixed(3)}°C (pixels: ${easternCnt})`);
    console.log(`Western anomaly: ${westernVal?.toFixed(3)}°C (pixels: ${westernCnt})`);

    // 10. Validate results
    if (easternCnt === 0 || westernCnt === 0) {
        console.log("<answer>C2</answer>");
        return;
    }

    if (easternVal === null || westernVal === null || 
        Math.abs(easternVal) > 20 || Math.abs(westernVal) > 20) { // Sanity check for SST anomaly
        console.log("<answer>C3</answer>");
        return;
    }

    // 11. Compare anomalies and output result
    if (easternVal > westernVal) {
        console.log("<answer>A</answer>");
    } else {
        console.log("<answer>B</answer>");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
